// ❌ OLD: The closure captures `big`, so the entire array stays alive
// on the heap for as long as `getFirst` exists — even though only
// big[0] is ever read.
function makeReader() {
  const big = loadHugeArray(); // ❌ OLD: 100MB array referenced by the closure
  // We only need the first element, but the closure keeps ALL of `big`.
  return () => big[0];
}

const getFirst = makeReader();
// getFirst stays referenced for the app's lifetime → `big` never GC'd.

function loadHugeArray() {
  // pretend this returns a very large array
  return new Array(10_000_000).fill(1);
}

// ✅ NEW: Extract the needed value BEFORE creating the closure so the
// closure captures only a tiny scalar, letting the large array be GC'd.
function makeReader() {
  const big = loadHugeArray();
  const first = big[0]; // ✅ NEW: only this small value is captured
  // `big` is no longer referenced by the returned closure.
  return () => first; // ✅ NEW: closure captures a single number, not the 100MB array
}

const getFirst = makeReader();
// `big` is unreferenced → eligible for garbage collection immediately.

function loadHugeArray() {
  return new Array(10_000_000).fill(1);
}
